describe('Search Results Sorting', () => {
  beforeEach(() => {
    cy.visit('/search');
  });

  it('should sort search results by relevance, price, and date', () => {
    // Perform a search
    cy.get('[data-testid="search-input"]').type('laptop');
    cy.get('[data-testid="search-button"]').click();

    // Verify search results are displayed
    cy.get('[data-testid="search-results-container"]').should('be.visible');
    cy.get('[data-testid="search-result-item"]').should('have.length.greaterThan', 0);

    // Verify default sort is by relevance
    cy.get('[data-testid="sort-dropdown"]').should('contain', 'Relevance');

    // Sort by price
    cy.get('[data-testid="sort-dropdown"]').click();
    cy.get('[data-testid="sort-option-price"]').click();

    // Verify results are sorted by price
    cy.get('[data-testid="sort-dropdown"]').should('contain', 'Price');
    cy.get('[data-testid="search-result-item"]').first().should('contain', '$1000');

    // Sort by date
    cy.get('[data-testid="sort-dropdown"]').click();
    cy.get('[data-testid="sort-option-date"]').click();

    // Verify results are sorted by date
    cy.get('[data-testid="sort-dropdown"]').should('contain', 'Date');
    cy.get('[data-testid="search-result-item"]').first().should('contain', '2024-10-20');

    // Sort by relevance again
    cy.get('[data-testid="sort-dropdown"]').click();
    cy.get('[data-testid="sort-option-relevance"]').click();

    // Verify results are sorted by relevance
    cy.get('[data-testid="sort-dropdown"]').should('contain', 'Relevance');
    cy.get('[data-testid="search-result-item"]').first().should('contain', 'Laptop Pro');
  });

  it('should handle sorting when no results are found', () => {
    // Perform a search with no results
    cy.get('[data-testid="search-input"]').type('nonexistentproduct123');
    cy.get('[data-testid="search-button"]').click();

    // Verify no results message is displayed
    cy.get('[data-testid="no-results-message"]').should('be.visible');
    cy.get('[data-testid="no-results-message"]').should('contain', 'No results found');

    // Verify sort dropdown is still visible but inactive
    cy.get('[data-testid="sort-dropdown"]').should('be.visible');
    cy.get('[data-testid="sort-dropdown"]').should('contain', 'Relevance');

    // Attempt to sort when no results exist
    cy.get('[data-testid="sort-dropdown"]').click();
    cy.get('[data-testid="sort-option-price"]').click();

    // Verify no change in state and no error
    cy.get('[data-testid="no-results-message"]').should('be.visible');
    cy.get('[data-testid="no-results-message"]').should('contain', 'No results found');
  });
});
